use std :: fs ; use std :: path :: Path ; use clap :: Parser ; use serde_json ; use num_bigint :: BigUint ; use cargo_vendormod :: group_atlas :: { GroupAtlas , GroupFamily , ClassicalLieType , TwistedLieType , SporadicGroup , n } ; use cargo_vendormod :: visualization :: { AtlasRenderer , AtlasConfig } ; # [doc = " Count number of families"] fn count_families (atlas : & GroupAtlas) -> usize { let mut families = std :: collections :: HashSet :: new () ; for group in & atlas . groups { families . insert (format ! ("{:?}" , group . family)) ; } families . len () }